from taf.sbts.oam.sc.rest.schemas.topology.topology_hw_connections_v1 import HwConnectionsTOPOLGYV1
from taf.sbts.oam.sc.rest.schemas.topology.topology_hw_description_v1 import HwDescriptionTOPOLGYV1


class HwObjectTOPOLGYV1(SchemaObject):
    instance_id = SchemaField(name="instance_id", not_null=False)
    _class = SchemaField(name="_class", not_null=True)
    uid = SchemaField(name="uid", not_null=True)
    description = SchemaField(name="description", klass=HwDescriptionTOPOLGYV1, not_null=False)
    connections = SchemaField(name="connections", klass=HwConnectionsTOPOLGYV1, many=True, not_null=False)
    type = SchemaField(name="type", not_null=False)
