    presence = SchemaField(name="presence", not_null=False)
    alarmed = SchemaField(name="alarmed", not_null=False)
    units_total = SchemaField(name="units_total", not_null=False)
    units_failed = SchemaField(name="units_failed", not_null=False)

    def __init__(self, instance_id=None, _class=None, uid=None, description=None, connections=None, type=None,
                 status=None, presence=None, alarmed=None, units_total=None, units_failed=None):
        self.instance_id = instance_id
        self._class = _class
        self.uid = uid
        self.description = description
        self.connections = connections
        self.type = type
        self.status = status
        self.presence = presence
        self.alarmed = alarmed
        self.units_total = units_total
        self.units_failed = units_failed

        super(HwObjectTOPOLGYV1, self).__init__()
